// ============================================================================================
// Regarding the Spotify section, due to the strict policies and terms of the Spotify platform,
// I had to adopt this last resort, using a method similar to 'hijacking' to utilize the official
// player. This is solely a measure of necessity and not malicious intent. If it violates any
// terms, I will promptly remove the code.
// ============================================================================================

'use strict';

// 注入到 Spotify 渲染进程主世界的桥 / Bridge injected into the Spotify renderer main world.
//
// 为什么是"运行时注入"而不是改文件（2026-11-18 在本机 1.3.9 实测）：
//   · 客户端用 rspack 打包，`v8_context_snapshot.bin` 把模块表反序列化成全局
//     `__webpack_modules__` / `rspackChunk`，页面加载完依然可直接用；
//   · `rspackChunk.push([[Symbol()], {}, re => re])` 能把真正的 `__webpack_require__` 骗出来；
//   · DI 容器（`Registry`）藏在 React fiber 的 `props.registry` 里，
//     `resolve(Symbol.for('PlayerAPI'))` 同步给出 PlayerAPI —— `play({uri})` / `seekTo` /
//     `skipToNext` / `_state` 全是真值，不是 DOM 抓来的二手数据。
//   · 所以**一个文件都不用改**，也不需要安装 Spicetify：`xpui.spa` 原封不动。
//
// 参照实现是 Spicetify 的 `src/jsHelper/spicetifyWrapper/{webpack,platform}.js` 与
// `src/preprocess/preprocess.go`（它把 `Spicetify._platform=` 补进快照才能做同样的事）。
// 我们只借用"怎么找到容器"这部分思路，其余一概不要。
//
// 页面每重载一次 window 就空了，需要重新注入；其余时间复用缓存的句柄。
// 注入后暴露 `window.__MR__`，方法一律返回 JSON 字符串（CDP 的 evaluate 只收标量）。
//
// nonce：每个对外方法都要求第一个实参是本次注入的随机串。端口已经改成随机的（见
// `spotify-client-probe.js`），万一还是被扫到，这一层至少让"连上 CDP"不等于"会发指令"——
// 攻击者得先去 Debugger 里逆闭包，而不是照着自己写一行 evaluate。它挡的是顺手，不是刻意。
// The nonce is an IIFE parameter, never a literal inside the function bodies: `toString()` on
// `__MR__.cmd` shows only the identifier. It raises the bar; it is not a security boundary.

function buildBridgeSource(nonce) {
  const secret = JSON.stringify(String(nonce || ''));
  return [
    '(function (NONCE) {',
    '  var PLAYER = Symbol.for("PlayerAPI");',
    '  var PLAYBACK = Symbol.for("PlaybackAPI");',
    '  if (window.__MR__ && window.__MR__.version === 2 && window.__MR__.ready && window.__MR__.ready()',
    '      && typeof window.__MR__.verify === "function" && window.__MR__.verify(NONCE) === true) {',
    '    return JSON.stringify({ ok: true, mode: "api", cached: true });',
    '  }',
    '',
    '  function authorized(token) {',
    '    return typeof token === "string" && token.length === NONCE.length && token === NONCE;',
    '  }',
    '',
    '  function denied() { return JSON.stringify({ ok: false, error: "E_TOKEN" }); }',
    '',
    '  function isRegistry(v) {',
    '    return !!v && typeof v === "object" && typeof v.resolve === "function"',
    '      && v._map && typeof v._map.get === "function";',
    '  }',
    '',
    '  // DI 容器是 PlatformProvider 的入参，只存在于 fiber 的 memoizedProps 里。',
    '  function findRegistry() {',
    '    var slots = ["#main", "body > div", "[data-testid=\\"now-playing-bar\\"]",',
    '                 "[data-testid=\\"now-playing-widget-v2\\"]", ".Root"];',
    '    var seeds = [];',
    '    for (var i = 0; i < slots.length; i++) {',
    '      var el = null;',
    '      try { el = document.querySelector(slots[i]); } catch (e) { el = null; }',
    '      if (!el) continue;',
    '      var keys = Object.keys(el);',
    '      for (var k = 0; k < keys.length; k++) {',
    '        if (keys[k].indexOf("__reactFiber$") === 0 || keys[k].indexOf("__reactContainer$") === 0) {',
    '          seeds.push(el[keys[k]]);',
    '          break;',
    '        }',
    '      }',
    '    }',
    '    if (!seeds.length) return null;',
    '    var seen = new WeakSet();',
    '    for (var s = 0; s < seeds.length; s++) {',
    '      var stack = [seeds[s]];',
    '      var guard = 0;',
    '      while (stack.length && guard < 14000) {',
    '        var f = stack.pop();',
    '        guard++;',
    '        if (!f || typeof f !== "object" || seen.has(f)) continue;',
    '        seen.add(f);',
    '        var props = f.memoizedProps;',
    '        if (props && typeof props === "object") {',
    '          if (isRegistry(props.registry)) return props.registry;',
    '          if (isRegistry(props)) return props;',
    '          if (props.platform) {',
    '            if (isRegistry(props.platform.Registry)) return props.platform.Registry;',
    '            if (isRegistry(props.platform)) return props.platform;',
    '          }',
    '        }',
    '        if (f.child) stack.push(f.child);',
    '        if (f.sibling) stack.push(f.sibling);',
    '      }',
    '    }',
    '    return null;',
    '  }',
    '',
    '  function ensure() {',
    '    var cached = window.__MR__;',
    '    if (cached && cached.player && cached.version === 2) {',
    '      try { if (cached.player._state) return cached; } catch (e) { /* 句柄失效，重建 */ }',
    '    }',
    '    var reg = findRegistry();',
    '    if (!reg) return null;',
    '    var player = null;',
    '    try { player = reg.resolve(PLAYER); } catch (e) { player = null; }',
    '    if (!player) return null;',
    '    var playback = null;',
    '    try { playback = reg.resolve(PLAYBACK); } catch (e) { playback = null; }',
    '    window.__MR__ = {',
    '      version: 2, player: player, playback: playback, registry: reg, at: Date.now(),',
    '      ready: ready, read: read, cmd: cmd, play: play, volume: volume, verify: verify,',
    '    };',
    '    return window.__MR__;',
    '  }',
    '',
    '  function verify(token) { return authorized(token) === true; }',
    '',
    '  function ready() {',
    '    var b = window.__MR__;',
    '    if (!b || !b.player) return false;',
    '    try { return !!b.player._state; } catch (e) { return false; }',
    '  }',
    '',
    '  // 进度是真值：positionAsOfTimestamp 是"某个时刻的位置"，timestamp 是那个时刻，',
    '  // 播放中要按经过时间外推，暂停/缓冲时不能外推。',
    '  function read(token) {',
    '    if (!authorized(token)) return denied();',
    '    var b = ensure();',
    '    if (!b) return JSON.stringify({ ok: false, error: "NO_BRIDGE" });',
    '    var st = null;',
    '    try { st = b.player._state; } catch (e) { st = null; }',
    '    if (!st) return JSON.stringify({ ok: false, error: "NO_STATE" });',
    '    var item = st.item || {};',
    '    var dur = Number(st.duration) || Number(item.duration && item.duration.milliseconds) || 0;',
    '    var pos = Number(st.positionAsOfTimestamp) || 0;',
    '    if (!st.isPaused && st.timestamp) pos += Math.max(0, Date.now() - Number(st.timestamp));',
    '    if (dur > 0 && pos > dur) pos = dur;',
    '    if (!(pos >= 0)) pos = 0;',
    '    var artists = [];',
    '    if (Object.prototype.toString.call(item.artists) === "[object Array]") {',
    '      for (var i = 0; i < item.artists.length; i++) {',
    '        var a = item.artists[i];',
    '        if (a && a.name) artists.push(String(a.name));',
    '      }',
    '    }',
    '    var vol = null;',
    '    try {',
    '      if (b.playback && typeof b.playback.__volume === "number") {',
    '        vol = Math.round(b.playback.__volume * 100);',
    '      }',
    '    } catch (e) { vol = null; }',
    '    return JSON.stringify({',
    '      ok: true,',
    '      state: {',
    '        uri: String(item.uri || ""),',
    '        title: String(item.name || ""),',
    '        artist: artists.join(", "),',
    '        album: String((item.metadata && item.metadata.album_title) || ""),',
    '        durationMs: Math.round(dur),',
    '        positionMs: Math.round(pos),',
    '        isPlaying: !st.isPaused,',
    '        isBuffering: !!st.isBuffering,',
    '        volume: vol,',
    '        hasProgress: dur > 0,',
    '        source: "api",',
    '      },',
    '    });',
    '  }',
    '',
    '  function cmd(token, name, payload) {',
    '    if (!authorized(token)) return denied();',
    '    var b = ensure();',
    '    if (!b) return JSON.stringify({ ok: false, error: "NO_BRIDGE" });',
    '    var p = payload || {};',
    '    var done = function () { return JSON.stringify({ ok: true }); };',
    '    var fail = function (e) {',
    '      return JSON.stringify({ ok: false, error: String((e && e.message) || e || "COMMAND_FAILED") });',
    '    };',
    '    var wrap = function (v) { return (v && typeof v.then === "function") ? v.then(done, fail) : done(); };',
    '    try {',
    '      var st = b.player._state || {};',
    '      switch (name) {',
    '        case "Play": return st.isPaused ? wrap(b.player.resume()) : done();',
    '        case "Pause": return st.isPaused ? done() : wrap(b.player.pause());',
    '        case "TogglePlay": return wrap(st.isPaused ? b.player.resume() : b.player.pause());',
    '        case "NextSong": return wrap(b.player.skipToNext());',
    '        case "PreviousSong": return wrap(b.player.skipToPrevious());',
    '        case "Seek": return wrap(b.player.seekTo(Math.max(0, Math.round(Number(p.position) || 0))));',
    '        case "SetVolume":',
    '          if (!b.playback) return JSON.stringify({ ok: false, error: "NO_PLAYBACK_API" });',
    '          return wrap(b.playback.setVolume(Math.max(0, Math.min(1, Number(p.level) || 0))));',
    '        default: return JSON.stringify({ ok: false, error: "unsupported command" });',
    '      }',
    '    } catch (e) { return fail(e); }',
    '  }',
    '',
    '  // 给 URI 就直接播，不搜索、不点 DOM，也不会播成另一版录音。',
    '  function play(token, uri) {',
    '    if (!authorized(token)) return denied();',
    '    var b = ensure();',
    '    if (!b) return JSON.stringify({ ok: false, error: "NO_BRIDGE" });',
    '    var target = String(uri || "");',
    '    if (!target) return JSON.stringify({ ok: false, error: "NO_URI" });',
    '    var done = function () { return JSON.stringify({ ok: true, uri: target }); };',
    '    var fail = function (e) {',
    '      return JSON.stringify({ ok: false, error: String((e && e.message) || e || "PLAY_FAILED") });',
    '    };',
    '    try {',
    '      var r = b.player.play({ uri: target }, {}, {});',
    '      return (r && typeof r.then === "function") ? r.then(done, fail) : done();',
    '    } catch (e) { return fail(e); }',
    '  }',
    '',
    '  // PlaybackAPI.getVolume() 返回 Promise<number>，域是 0..1。',
    '  function volume(token) {',
    '    if (!authorized(token)) return denied();',
    '    var b = ensure();',
    '    if (!b || !b.playback) return JSON.stringify({ ok: false, error: "NO_PLAYBACK_API" });',
    '    var fmt = function (n) {',
    '      var level = typeof n === "number" ? n : null;',
    '      return JSON.stringify({ ok: level != null, volume: level });',
    '    };',
    '    try {',
    '      var v = b.playback.getVolume();',
    '      return (v && typeof v.then === "function") ? v.then(fmt, function () { return JSON.stringify({ ok: false }); }) : fmt(v);',
    '    } catch (e) {',
    '      return JSON.stringify({ ok: false, error: String((e && e.message) || e) });',
    '    }',
    '  }',
    '',
    '  var handle = ensure();',
    '  if (!handle) return JSON.stringify({ ok: false, error: "NO_REGISTRY" });',
    '  return JSON.stringify({ ok: true, mode: "api", cached: false, ready: ready() });',
    '})(' + secret + ')',
  ].join('\n');
}

// 静态检查与测试用的样张；真正注入时走 `buildBridgeSource(每次随机的 nonce)`。
const BRIDGE_SOURCE = buildBridgeSource('__MR_BRIDGE_NONCE__');

module.exports = { BRIDGE_SOURCE, buildBridgeSource };
